import Foundation
import Security

/// Supabase（*.supabase.co）の証明書の確認。
/// 古い iPadOS（例：iPad 第6世代の iPadOS 17、トラストストア 2024年4月版）は
/// 現在の Google Trust Services の証明書チェーンを信頼できないことがあるため、
/// 端末の確認が失敗したときだけ、アプリに同梱した主要な認証局のルート証明書
/// （Google・Let's Encrypt・DigiCert・Sectigo・SSL.com・GlobalSign・Amazon）を基準に確認し直す。
/// Supabase が証明書の発行元を変えても、古い iPad で接続が止まらないようにするため。ホスト名・有効期限・署名の検証は通常どおり行う。
final class SupabaseTrust: NSObject, URLSessionDelegate {
    static let shared = SupabaseTrust()

    /// 通信はすべてこのセッションを使う
    static let session = URLSession(configuration: .default, delegate: SupabaseTrust.shared, delegateQueue: nil)

    private let anchors: [SecCertificate] = [
        // GTS Root R1
        "",
        // GTS Root R3
        "",
        // GTS Root R4
        "",
        // ISRG Root X1（Let's Encrypt）
        "",
        // ISRG Root X2（Let's Encrypt）
        "",
        // DigiCert Global Root G2
        "",
        // DigiCert Global Root G3
        "",
        // USERTrust ECC（Sectigo）
        "",
        // USERTrust RSA（Sectigo）
        "",
        // SSL.com Root ECC
        "",
        // SSL.com Root RSA
        "",
        // GlobalSign Root R3
        "",
        // Amazon Root CA 1
        "",
        // Amazon Root CA 3
        "",
    ].compactMap { b64 in
        guard let data = Data(base64Encoded: b64) else { return nil }
        return SecCertificateCreateWithData(nil, data as CFData)
    }

    func urlSession(_ session: URLSession,
                    didReceive challenge: URLAuthenticationChallenge,
                    completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        let space = challenge.protectionSpace
        guard space.authenticationMethod == NSURLAuthenticationMethodServerTrust,
              let trust = space.serverTrust,
              space.host == "supabase.co" || space.host.hasSuffix(".supabase.co") else {
            completionHandler(.performDefaultHandling, nil)
            return
        }
        // まず端末の標準の確認
        if SecTrustEvaluateWithError(trust, nil) {
            completionHandler(.useCredential, URLCredential(trust: trust))
            return
        }
        // 失敗したら同梱した主要な認証局のルートだけを基準に確認し直す
        SecTrustSetAnchorCertificates(trust, anchors as CFArray)
        SecTrustSetAnchorCertificatesOnly(trust, true)
        if SecTrustEvaluateWithError(trust, nil) {
            completionHandler(.useCredential, URLCredential(trust: trust))
        } else {
            completionHandler(.cancelAuthenticationChallenge, nil)
        }
    }
}
